old_string:
const pointsFor = vals => vals.map((v,i)=>[x(i), y(v), v]);
const smoothPath = vals => {
  const pts = pointsFor(vals);
  if (!pts.length) return '';
  if (pts.length === 1) return `M ${pts[0][0].toFixed(1)} ${pts[0][1].toFixed(1)}`;
  let dPath = `M ${pts[0][0].toFixed(1)} ${pts[0][1].toFixed(1)}`;
  for (let i=0; i<pts.length-1; i++) {
    const [x0,y0] = pts[i]; const [x1,y1] = pts[i+1];
    const cpX = x0 + (x1 - x0) * 0.5;
    dPath += ` C ${cpX.toFixed(1)} ${y0.toFixed(1)}, ${cpX.toFixed(1)} ${y1.toFixed(1)}, ${x1.toFixed(1)} ${y1.toFixed(1)}`;
  }
  return dPath;
};
const totalVals = days.map(day => day.total || 0);
const areaPath = totalVals.length ? `${smoothPath(totalVals)} L ${x(days.length-1).toFixed(1)} ${H-padB} L ${x(0).toFixed(1)} ${H-padB} Z` : '';
